        // Penalty for leaving a gap that is too small to fit typical items (1-10)
        // but too large to be ignored.
        let fragmentation_penalty = (post_residual as f64).powi(2) / (bin_capacity as f64 * 0.15);

        // Lookahead: Reward bins that can accommodate the next item perfectly.
        // If post_residual == next_item_size, we get a massive reward.
