        // As the stream progresses, the penalty for new bins increases to force packing into existing ones.
        score = 85.0 + (mean_residual * 0.75) + (progress * 40.0) - (open_bins_count as f64 * 0.05);
    } else {
        // 3. Lookahead Synergy: Reward bins that can accommodate the next item.
