    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    // We penalize high post_residual values to keep bins tightly packed.
    let mut score = post_res.powi(2);

    // Penalty for creating "slivers" (very small residuals) that are likely unusable
    // if the next item is large. We weight this by progress.
    if post_res > 0.0 && post_res < 10.0 {
        score += (10.0 - post_res) * 5.0 * (1.0 + progress);
    }

    // Lookahead logic: If the next item exists, penalize bins that cannot fit it
    // if the current bin is the only one that could have accommodated it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size as f64 - post_res) * 2.5;
        }
    }

    // Adaptive threshold for opening new bins:
    // As the stream progresses, be more conservative about opening new bins
    // unless the current fit is extremely poor (large post_residual).
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate. 
        // We only return a low score if the mean residual of existing bins is already very low,
        // suggesting that existing bins are too full to accommodate future items.
        score = 40.0 + (mean_residual * 0.5) - (progress * 15.0);
    } else {
        // Reward bins that bring the residual closer to the global mean,
        // promoting uniform bin utilization.
        let deviation = (post_res - mean_residual).abs();
        score += deviation * 0.8;

        // Penalize bins that are "last chances" if they create a poor fit.
        if fitting_bins_count == 1 && post_res > 20.0 {
            score += 15.0;
        }
    }

    score
}

