    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If post_residual is in the range [1, 9], it is highly likely to be wasted
    // because the minimum item size is 10. Heavily penalize these "unusable" gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    }

    // 2. Adaptive Lookahead: If the next item is large and the current placement leaves a gap
    // that is too small for the next item, penalize it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 150.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the fit is excellent.
    // If we are considering a new bin (bin_residual == bin_capacity), apply a penalty
    // proportional to the number of bins already open to encourage consolidation.
    if bin_residual == bin_capacity {
        score += 80.0 + (open_bins_count as f64 * 5.0);
    }

    // 4. Fitting Bin Scarcity: If this is the ONLY bin that can fit the item, 
    // we should prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // 5. Mean Residual Balancing: Penalize bins that deviate significantly from the mean 
    // residual to keep the filling levels of open bins somewhat uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 6. Progressive Tightening: As the stream progresses, prioritize tighter packing
    // to avoid leaving too many fragmented bins at the end.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

